CREATE SET TABLE MDP01_META.META_BUSINESS_OBJECT ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      business_object_id INTEGER NOT NULL,      business_object_name VARCHAR(100) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      business_object_code VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      beschreibung VARCHAR(2000) CHARACTER SET LATIN NOT CASESPECIFIC,      layer_id INTEGER NOT NULL,      ersterfassungsdatum TIMESTAMP(6) NOT NULL,      aenderungsdatum TIMESTAMP(6) NOT NULL)PRIMARY INDEX ( business_object_id )UNIQUE INDEX ( business_object_code );